package com.greenocean.backend.professional.service;
import com.greenocean.backend.common.exception.*;
import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;
import java.util.*;import java.io.IOException;
@Service @Transactional
public class ClinicalFiles {
 private final JdbcTemplate db;private final ClinicalCare care;private final CredentialScanner scanner;
 public ClinicalFiles(JdbcTemplate db,ClinicalCare care,CredentialScanner scanner){this.db=db;this.care=care;this.scanner=scanner;}
 public UUID upload(UUID who,UUID session,UUID encounter,UUID previous,MultipartFile file){UUID policy=care.attachmentPolicy();care.attachmentAccess(who,session,encounter,policy,true);if(file==null||file.isEmpty()||file.getSize()>2097152)throw new IllegalArgumentException("Clinical documents must be1 byte to2 MB");String mime=Objects.toString(file.getContentType(),"");byte[] bytes;try{bytes=file.getBytes();}catch(IOException unavailable){throw new IllegalArgumentException("Clinical attachment could not be inspected");}boolean valid=switch(mime){case "application/pdf"->prefix(bytes,new byte[]{'%','P','D','F','-'});case "image/jpeg"->prefix(bytes,new byte[]{(byte)255,(byte)216,(byte)255});case "image/png"->prefix(bytes,new byte[]{(byte)137,'P','N','G',13,10,26,10});default->false;};if(!valid)throw new IllegalArgumentException("Only matching PDF, JPEG or PNG content is accepted");if(previous!=null&&!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM clinic_attachments WHERE id=? AND encounter_id=? AND owner_id=?)",Boolean.class,previous,encounter,who)))throw new NotFoundException("Own prior attachment was not found");if(db.queryForObject("SELECT count(*) FROM clinic_attachments WHERE encounter_id=?",Integer.class,encounter)>=50)throw new ConflictException("The bounded attachment limit has been reached");UUID id=UUID.randomUUID();var result=scanner.scan(bytes);db.update("INSERT INTO clinic_attachments(id,encounter_id,owner_id,policy_id,content_type,body_cipher,byte_size,scan_state,scanner_reference,previous_id) VALUES(?,?,?,?,?,?,?,?,?,?)",id,encounter,who,policy,mime,care.sealBytes(bytes,"attachment:"+encounter+":"+id+":"+who),bytes.length,result.state(),result.reference(),previous);care.audit(who,session,encounter,"ATTACHMENT_QUARANTINED",id,null);return id;}
 private boolean prefix(byte[] bytes,byte[] expected){if(bytes.length<expected.length)return false;for(int i=0;i<expected.length;i++)if(bytes[i]!=expected[i])return false;return true;}
 public List<Map<String,Object>> list(UUID who,UUID session,UUID encounter){UUID policy=care.attachmentPolicy();var permitted=care.attachmentAccess(who,session,encounter,policy,false);var rows=db.queryForList("SELECT id,owner_id,policy_id,content_type,byte_size,scan_state,previous_id,created_at FROM clinic_attachments WHERE encounter_id=? ORDER BY created_at,id LIMIT 50",encounter);for(var r:rows){care.attachmentAccess(who,session,encounter,(UUID)r.remove("policy_id"),false);}care.audit(who,session,encounter,"ATTACHMENTS_LISTED",null,(UUID)permitted.get("accessGrantId"));return rows;}
 public String rescan(UUID who,UUID session,UUID encounter,UUID id){var r=record(encounter,id);care.attachmentAccess(who,session,encounter,(UUID)r.get("policy_id"),true);if(!who.equals(r.get("owner_id")))throw new ForbiddenException("Only the original uploader can retry scanning");if(!"PENDING".equals(r.get("scan_state")))return(String)r.get("scan_state");var result=scanner.scan(plain(r));db.update("UPDATE clinic_attachments SET scan_state=?,scanner_reference=? WHERE id=?",result.state(),result.reference(),id);care.audit(who,session,encounter,"ATTACHMENT_SCANNED",id,null);return result.state();}
 public record Download(byte[] bytes,String mime,String filename){}
 public Download download(UUID who,UUID session,UUID encounter,UUID id){var r=record(encounter,id);var permitted=care.attachmentAccess(who,session,encounter,(UUID)r.get("policy_id"),false);if(!"CLEAN".equals(r.get("scan_state")))throw new ForbiddenException("Unscanned or rejected clinical files cannot be used");care.audit(who,session,encounter,"ATTACHMENT_DOWNLOADED",id,(UUID)permitted.get("accessGrantId"));String mime=(String)r.get("content_type");return new Download(plain(r),mime,"clinical-document."+(mime.equals("application/pdf")?"pdf":mime.equals("image/png")?"png":"jpg"));}
 private Map<String,Object> record(UUID encounter,UUID id){var rows=db.queryForList("SELECT * FROM clinic_attachments WHERE id=? AND encounter_id=? FOR UPDATE",id,encounter);if(rows.isEmpty())throw new NotFoundException("Clinical attachment was not found");return rows.getFirst();}
 private byte[] plain(Map<String,Object> r){return care.openBytes((byte[])r.get("body_cipher"),"attachment:"+r.get("encounter_id")+":"+r.get("id")+":"+r.get("owner_id"));}
}
